mapper.delete:
		update REP_FLOAT_FEE
		set STATUS = 'D',
            UPDATE_USER = #{updateUser,jdbcType=VARCHAR},
            UPDATE_TIME = #{updateTime,jdbcType=TIMESTAMP}
		where PROD_ID = #{prodId,jdbcType=CHAR}
          and AFFIRM_DATE = #{affirmDate,jdbcType=DATE}

mapper.select:
select T.PROD_ID prodId, rpi.PROD_NAME prodName, T.AFFIRM_DATE affirmDate, T.BUSINESS_CODE businessCode, T.AFFIRM_NUM affirmNum, T.AFFIRM_AMT affirmAmt, T.ABOVE_AMT aboveAmt, T.STATUS status, T.UPDATE_USER updateUser, T.UPDATE_TIME updateTime, T.ERRORMSG errorMsg from REP_FLOAT_FEE T left join REP_PROD_INFO rpi on rpi.PROD_ID = T.PROD_ID
#{item,jdbcType=VARCHAR}
and T.AFFIRM_DATE >= to_date(#{startDate,jdbcType=DATE},'yyyy-MM-dd')
and T.AFFIRM_DATE <= to_date(#{endDate,jdbcType=DATE},'yyyy-MM-dd')
and T.STATUS = #{status,jdbcType=VARCHAR}

select T.*
from REP_FLOAT_FEE T
where T.PROD_ID = #{prodId,jdbcType=VARCHAR}
        and T.AFFIRM_DATE = #{affirmDate,jdbcType=DATE}
        and T.STATUS = 'E'

select distinct T.*
from REP_FLOAT_FEE T
where T.PROD_ID = #{prodId,jdbcType=VARCHAR}
and T.AFFIRM_DATE = #{affirmDate,jdbcType=DATE}
and T.STATUS = 'D'
